            if 0 <= x < W and 0 <= y < H:
                obs.add((x, y))
        except Exception:
            pass

    opp_tr = set(tuple(t) for t in (observation.get("opponent_territory") or []))

    def valid(x, y):
        return 0 <= x < W and 0 <= y < H and (x, y) not in obs

